import Ajv from 'ajv';
import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema registration', () => {
  it('rejects an invalid static schema at registration with the tool name', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Invalid location schema',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });
});

describe('ToolRegistry dynamic schemas', () => {
  // specs/hal-engine-tool-input-validation/spec.md#9
  it('validates each resolved schema and compiles each schema object once', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    try {
      const registry = new ToolRegistry();
      const locationSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      const unitsSchema = {type: 'object', properties: {units: {type: 'string'}}, required: ['units']};
      let currentSchema: Record<string, unknown> = locationSchema;
      const executor = jest.fn(async () => 'ok');
      registry.register(() => ({name: 'weather', description: 'Weather', inputSchema: currentSchema}), executor);

      await registry.execute('weather', {location: 'Paris'});
      await registry.execute('weather', {location: 'Berlin'});
      currentSchema = unitsSchema;
      const rejected = await registry.execute('weather', {location: 'Paris'});

      expect({
        rejected: /units.*required|required.*units/i.test(rejected.result),
        calls: executor.mock.calls,
        compilations: compile.mock.calls,
      }).toEqual({
        rejected: true,
        calls: [
          [{location: 'Paris'}, undefined],
          [{location: 'Berlin'}, undefined],
        ],
        compilations: [[locationSchema], [unitsSchema]],
      });
    } finally {
      compile.mockRestore();
    }
  });
});

describe('ToolRegistry static schemas', () => {
  // specs/hal-engine-tool-input-validation/spec.md#8
  it('keeps using the schema compiled at registration', async () => {
    const registry = new ToolRegistry();
    const definition = {
      name: 'weather',
      description: 'Weather',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    const executor = jest.fn(async () => 'ok');
    registry.register(definition, executor);

    definition.inputSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['units']};
    const response = await registry.execute('weather', {location: 'Paris'});

    expect({response, calls: executor.mock.calls}).toEqual({
      response: {result: 'ok'},
      calls: [[{location: 'Paris'}, undefined]],
    });
  });
});

describe('ToolRegistry input rejection', () => {
  // specs/hal-engine-tool-input-validation/spec.md#4
  it('reports a nested escaped property name as a full field path', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile').mockImplementation(() => {
      return Object.assign(() => false, {
        errors: [{dataPath: ".location['user/id']", params: {type: 'string'}, keyword: 'type'}],
      }) as unknown as ReturnType<Ajv['compile']>;
    });
    try {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'weather',
          description: 'Weather',
          inputSchema: {type: 'object', properties: {location: {type: 'object'}}},
        },
        async () => 'unreachable'
      );

      const response = await registry.execute('weather', {location: {'user/id': 42}});

      expect(response.result).toBe('/location/user/id must be string');
    } finally {
      compile.mockRestore();
    }
  });

  // specs/hal-engine-tool-input-validation/spec.md#4
  it('reports escaped JSON pointer property names as readable field paths', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {'user/id': {type: 'string'}}},
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('weather', {'user/id': 42});

    expect(response.result).toBe('/user/id must be string');
  });

  // specs/hal-engine-tool-input-validation/spec.md#3
  it('names the full path of a nested required property', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'object', properties: {city: {type: 'string'}}, required: ['city']}},
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('weather', {location: {}});

    expect(response.result).toMatch(/location[/.]city.*required/);
  });
});

describe('ToolRegistry valid input', () => {
  // specs/hal-engine-tool-input-validation/spec.md#5
  it('passes valid input with an extra property to the executor unchanged once', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      executor
    );
    const input = {location: 'Paris', note: 'keep me'};

    const response = await registry.execute('weather', input);

    expect({response, calls: executor.mock.calls}).toEqual({response: {result: 'ok'}, calls: [[input, undefined]]});
  });
});
import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as unknown as ConstructorParameters<
    typeof Ajv
  >[0]);
  private readonly validators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(schema: Record<string, unknown>): ValidateFunction {
    let validator = this.validators.get(schema);
    if (!validator) {
      validator = this.ajv.compile(schema);
      this.validators.set(schema, validator);
    }
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.validatorFor(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  private rejectInput(name: string, validate: ValidateFunction): ToolResponse {
    const error = validate.errors?.[0];
    const details = error as unknown as
      {instancePath?: string; dataPath?: string; params: Record<string, unknown>; keyword: string} | undefined;
    const rawPath = details?.instancePath ?? details?.dataPath ?? '';
    const fieldPath = rawPath
      .replace(/\[['"]([^'"]+)['"]\]/g, '/$1')
      .replace(/\.([^.[\]]+)/g, '/$1')
      .replace(/~1/g, '/')
      .replace(/~0/g, '~');
    const field =
      details?.keyword === 'required'
        ? `${fieldPath}${fieldPath ? '/' : ''}${String(details.params.missingProperty)}`
        : fieldPath || 'input';
    const constraint =
      details?.keyword === 'type'
        ? `must be ${String(details.params.type)}`
        : details?.keyword === 'required'
          ? 'is required'
          : `failed ${details?.keyword ?? 'schema'} constraint`;
    const result = `${field} ${constraint}`;
    log.warn('tool', 'input rejected', {name, field, constraint});
    return {result};
  }

  /** Validates tool input as specified in specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = tool.validator ?? this.validatorFor(this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validate(input)) return this.rejectInput(name, validate);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
